var N=["brightness","warmth","contrast","exposure","highlights","shadows","fade","saturation","vibrance","clarity","sharpness","vignette"],Q=()=>Object.fromEntries(N.map(n=>[n,0])),A=n=>({min:["fade","sharpness","vignette"].includes(n)?0:-100,max:100});function S(n,a){let i=Number(a);return N.includes(n)&&Number.isFinite(i)?Math.min(A(n).max,Math.max(A(n).min,i)):null}function T(n,a,i,s,x=0,p=i,b=new Uint8ClampedArray(n.length)){let E=(s.brightness||0)*.7,O=2**((s.exposure||0)/50),z=2**((s.contrast||0)/100),C=1+(s.saturation||0)/100,d=(s.warmth||0)*.3,g=(s.fade||0)/100,u=(s.sharpness||0)/100,y=(s.clarity||0)/100,F=(s.vignette||0)/100,P=(s.shadows||0)*.6,U=(s.highlights||0)*.6,k=(s.vibrance||0)/100,q=u!==0||y!==0;if(!Object.values(s).some(r=>r!==0))return b.set(n.subarray(x*a*4,p*a*4),x*a*4),b;for(let r=x;r<p;r++)for(let c=0;c<a;c++){let e=(r*a+c)*4,m=n[e],l=n[e+1],h=n[e+2],f=(.2126*m+.7152*l+.0722*h)/255,B=P*(1-f)*(1-f)+U*f*f,D=k*(1-(Math.max(m,l,h)-Math.min(m,l,h))/255),G=c?e-4:e,H=c<a-1?e+4:e,I=r?e-a*4:e,J=r<i-1?e+a*4:e;for(let t=0;t<3;t++){let o=(n[e+t]*O+E+B-127.5)*z+127.5;if(o+=t===0?d:t===2?-d:0,q){let j=n[e+t]-(n[G+t]+n[H+t]+n[I+t]+n[J+t])/4;o+=j*u*1.5+j*y*(1-Math.abs(f-.5))}t===0?m=o:t===1?l=o:h=o}let M=.2126*m+.7152*l+.0722*h,K=((c-a/2)/(a/2))**2+((r-i/2)/(i/2))**2,L=1-Math.min(.85,K*.32*F);for(let t=0;t<3;t++){let o=M+((t===0?m:t===1?l:h)-M)*Math.max(0,C+D);b[e+t]=(o*(1-g*.45)+42*g)*L}b[e+3]=n[e+3]}return b}export{Q as a,A as b,S as c,T as d};
